'use strict';
const MATERIALS = Object.freeze({cardboard:{name:'Cardboard',cost:1,strength:1,color:'#cfaa71',edge:'#98764a'},wood:{name:'Wood',cost:2,strength:3,color:'#c3844b',edge:'#80502e'},steel:{name:'Steel',cost:4,strength:5,color:'#8aa2a2',edge:'#4e6b70'}});
// All game rules live here. This function has no drawing, DOM, or mutable state.
function simulateBridge(slots, load) {
  if (!Array.isArray(slots) || slots.length !== 3 || !Number.isInteger(load) || load < 5 || load > 15) return {valid:false,reason:'Invalid bridge or load.'};
  let cost=0,strength=0;
  for(const slot of slots){if(slot===null) continue;if(!Object.hasOwn(MATERIALS,slot))return {valid:false,reason:'Unknown material.'};cost+=MATERIALS[slot].cost;strength+=MATERIALS[slot].strength;}
  const reason=cost>8?'Over budget. Use no more than 8 coins.':slots.includes(null)?'Choose a material for all three spans.':'';
  return {valid:!reason,reason,cost,strength,load,passes:!reason && strength>=load};
}
window.simulateBridge=simulateBridge;
const $=id=>document.getElementById(id),canvas=$('scene'),ctx=canvas.getContext('2d');
const state={slots:[null,null,null],load:11,prediction:null,mode:'build',elapsed:0,paused:false,result:null,history:[]};
let selectedMaterial=null,drag=null;
$('slots').innerHTML=[0,1,2].map(i=>'<div class="slot"><label>SPAN 0'+(i+1)+'</label><button class="drop-slot" id="slot-'+i+'" aria-label="Place selected material in span '+(i+1)+'">Drop piece here</button><small id="detail-'+i+'">Drag a piece here.</small><button class="remove-piece quiet" data-remove="'+i+'" aria-label="Remove span '+(i+1)+'">Remove ×</button></div>').join('');
const pieceArt=key=>'<svg viewBox="0 0 200 65" aria-hidden="true"><path d="M8 12H192V56H8Z M12 54L65 15L125 54L188 15" fill="none" stroke="'+MATERIALS[key].edge+'" stroke-width="9"/><rect x="3" y="3" width="194" height="13" rx="3" fill="'+MATERIALS[key].color+'" stroke="'+MATERIALS[key].edge+'" stroke-width="3"/></svg>';
document.querySelectorAll('.material').forEach((old,i)=>{const key=Object.keys(MATERIALS)[i],m=MATERIALS[key],b=document.createElement('button');b.className='material piece '+key;b.dataset.material=key;b.setAttribute('aria-pressed','false');b.innerHTML=pieceArt(key)+'<span><strong>'+m.name+'</strong><small>'+m.cost+' coin'+(m.cost===1?'':'s')+' · '+m.strength+' strength</small></span>';old.replaceWith(b);});
function selectMaterial(key){selectedMaterial=key;document.querySelectorAll('.piece').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.material===key)));}
function place(i,key){if(state.mode==='testing'||!key)return;state.slots[i]=key;changed();}
function targetAt(x,y){const el=document.elementFromPoint(x,y),slot=el?.closest('.drop-slot');if(slot)return Number(slot.id.split('-')[1]);const r=canvas.getBoundingClientRect(),cx=(x-r.left)/r.width*1100,cy=(y-r.top)/r.height*490;if(cx>=250&&cx<850&&cy>=245&&cy<=370)return Math.floor((cx-250)/200);return null;}
document.querySelectorAll('.piece').forEach(b=>{b.addEventListener('click',()=>{if(state.mode!=='testing')selectMaterial(b.dataset.material);});b.addEventListener('pointerdown',e=>{if(state.mode==='testing'||e.button!==0)return;selectMaterial(b.dataset.material);b.setPointerCapture(e.pointerId);drag={key:b.dataset.material,x:e.clientX,y:e.clientY,ghost:null};});b.addEventListener('pointermove',e=>{if(!drag)return;if(!drag.ghost&&Math.hypot(e.clientX-drag.x,e.clientY-drag.y)>6){drag.ghost=document.createElement('div');drag.ghost.className='drag-ghost';drag.ghost.innerHTML=pieceArt(drag.key);document.body.append(drag.ghost);}if(drag.ghost){drag.ghost.style.left=e.clientX+'px';drag.ghost.style.top=e.clientY+'px';document.querySelectorAll('.drop-slot').forEach((s,i)=>s.classList.toggle('drop-hover',targetAt(e.clientX,e.clientY)===i));}});b.addEventListener('pointerup',e=>{if(!drag)return;const i=targetAt(e.clientX,e.clientY);if(drag.ghost&&i!==null)place(i,drag.key);drag.ghost?.remove();drag=null;document.querySelectorAll('.drop-hover').forEach(s=>s.classList.remove('drop-hover'));});b.addEventListener('pointercancel',()=>{drag?.ghost?.remove();drag=null;document.querySelectorAll('.drop-hover').forEach(s=>s.classList.remove('drop-hover'));});});
[0,1,2].forEach(i=>{$('slot-'+i).addEventListener('click',()=>place(i,selectedMaterial));document.querySelector('[data-remove="'+i+'"]').addEventListener('click',()=>{if(state.mode==='testing')return;state.slots[i]=null;changed();});});
canvas.addEventListener('click',e=>{const i=targetAt(e.clientX,e.clientY);if(i!==null)place(i,selectedMaterial);});
function setMessage(title,body,kind=''){$('message').className='message '+kind;$('message').replaceChildren();const b=document.createElement('strong');b.textContent=title;$('message').append(b,document.createTextNode(body));}
function changed(){state.mode='build';state.result=null;state.elapsed=0;state.prediction=null;document.querySelectorAll('[data-prediction]').forEach(b=>b.setAttribute('aria-pressed','false'));setMessage('A new idea. Make a prediction.','Will this combination carry the rover? Choose your prediction, then test.');sync();draw();}
$('load').addEventListener('input',e=>{state.load=Number(e.target.value);changed();});
document.querySelectorAll('[data-prediction]').forEach(b=>b.addEventListener('click',()=>{state.prediction=b.dataset.prediction;document.querySelectorAll('[data-prediction]').forEach(x=>x.setAttribute('aria-pressed',String(x===b)));}));
function sync(){const r=simulateBridge(state.slots,state.load),running=state.mode==='testing';$('cost').textContent=r.cost;$('cost').className=r.cost>8?'over':'';$('coins').innerHTML=Array.from({length:8},(_,i)=>`<span class="coin ${i>=r.cost?'unspent':''}"></span>`).join('');$('load-value').value=state.load;$('phase').textContent=running?(state.paused?'TEST PAUSED':'TEST IN PROGRESS'):state.mode==='result'?'TEST COMPLETE':'READY TO BUILD';[0,1,2].forEach(i=>{const m=MATERIALS[state.slots[i]];$('detail-'+i).textContent=m?`${m.cost} coin${m.cost===1?'':'s'} · ${m.strength} strength`:'An open space. Your call.';$('slot-'+i).disabled=running;$('slot-'+i).innerHTML=m?pieceArt(state.slots[i])+'<span>'+m.name+'</span>':'Drop piece here';document.querySelector('[data-remove="'+i+'"]').disabled=running||!m;});document.querySelectorAll('.piece').forEach(b=>b.disabled=running);$('load').disabled=running;document.querySelectorAll('[data-prediction]').forEach(b=>b.disabled=running);$('test').disabled=running;$('test').innerHTML=state.mode==='result'?'Test again <span>↻</span>':'Test the bridge <span>→</span>';$('pause').hidden=!running;$('pause').textContent=state.paused?'Resume test':'Pause test';}
$('test').addEventListener('click',()=>{const result=simulateBridge(state.slots,state.load);if(!result.valid){setMessage('Build needs a rethink.',result.reason,'fail');return;}state.result=result;state.mode='testing';state.elapsed=0;state.paused=false;setMessage('Test in progress…',`The rover is carrying load ${state.load}. Watch your bridge.`);sync();});
$('pause').addEventListener('click',()=>{state.paused=!state.paused;sync();});
$('reset').addEventListener('click',()=>{state.slots=[null,null,null];state.load=11;state.history=[];state.paused=false;selectMaterial(null);$('load').value=11;changed();history();setMessage('A fresh experiment.','Build a bridge, make a prediction, then see what happens.');});
function history(){$('history').replaceChildren();if(!state.history.length){$('history').innerHTML='<p>Your discoveries will appear here. Try a weak bridge first.</p>';return;}state.history.slice().reverse().forEach((r,i)=>{const row=document.createElement('div');row.className='record';row.innerHTML=`<span>${String(state.history.length-i).padStart(2,'0')}</span><span>${r.slots.map(k=>MATERIALS[k].name).join(' + ')}<small style="display:block;margin-top:4px">${r.cost} coins · strength ${r.strength} · load ${r.load}</small></span><b class="${r.passes?'':'failed'}">${r.passes?'PASS':'FALL'}</b><span>${r.prediction?((r.prediction==='pass')===r.passes?'Called it ✓':'Surprise!'):'—'}</span>`;$('history').append(row);});}
function finish(){state.mode='result';const r=state.result;state.history.push({...r,slots:[...state.slots],prediction:state.prediction});const prediction=state.prediction?((state.prediction==='pass')===r.passes?' Your prediction was right.':' A surprise! What would you change?'):'';setMessage(r.passes?'Safe crossing!':'Splash! The bridge gave way.',`Strength ${r.strength} ${r.passes?'≥':'<'} load ${r.load}. ${r.passes?'The rover made it across.':'Revise the materials or lower the load and try again.'}${prediction}`,r.passes?'pass':'fail');sync();history();}
function update(ms){if(state.mode==='testing'&&!state.paused){state.elapsed=Math.min(4200,state.elapsed+ms);if(state.elapsed>=4200)finish();}}
function round(x,y,w,h,r,fill,stroke){ctx.beginPath();ctx.roundRect(x,y,w,h,r);ctx.fillStyle=fill;ctx.fill();if(stroke){ctx.strokeStyle=stroke;ctx.lineWidth=3;ctx.stroke();}}
function poly(points,color){ctx.beginPath();points.forEach(([x,y],i)=>i?ctx.lineTo(x,y):ctx.moveTo(x,y));ctx.closePath();ctx.fillStyle=color;ctx.fill();}
function line(x,y,a,b,color,width=3){ctx.beginPath();ctx.moveTo(x,y);ctx.lineTo(a,b);ctx.strokeStyle=color;ctx.lineWidth=width;ctx.stroke();}
function tree(x,y,s){ctx.save();ctx.translate(x,y);ctx.scale(s,s);round(-5,0,10,53,3,'#68795a');[[-18,0,30], [15,-15,32],[-5,-35,31]].forEach(([a,b,r])=>{ctx.beginPath();ctx.arc(a,b,r,0,7);ctx.fillStyle=b===-35?'#7c9f72':'#90ae7b';ctx.fill();});ctx.restore();}
function span(x,material,index){const m=MATERIALS[material];ctx.save();if(state.result&&!state.result.passes&&state.elapsed>2050){const f=Math.min(1,(state.elapsed-2050)/1300);ctx.translate(x+100,295+f*160);ctx.rotate((index-1)*f*.8+.12*f);ctx.translate(-x-100,-295);}if(!m){ctx.setLineDash([8,8]);ctx.strokeStyle='#7c9f8d';ctx.lineWidth=2;ctx.strokeRect(x+4,295,192,57);ctx.setLineDash([]);ctx.fillStyle='#6c8d7d';ctx.font='bold 18px Segoe UI';ctx.textAlign='center';ctx.fillText('0'+(index+1),x+100,330);}else{round(x,293,200,60,4,m.color,m.edge);ctx.fillStyle='#dbe6d6';ctx.fillRect(x+13,307,174,32);const c=m.edge;line(x+10,345,x+65,302,c,9);line(x+65,302,x+124,345,c,9);line(x+124,345,x+190,302,c,9);round(x-3,281,206,17,4,m.color,m.edge);if(material==='cardboard'){for(let a=x+10;a<x+195;a+=19)line(a,283,a+6,296,'#b58f58',1);}if(material==='wood'){for(let a=x+18;a<x+200;a+=36)line(a,283,a,296,'#996034',2);}if(material==='steel'){[x+8,x+192].forEach(a=>[290,343].forEach(b=>{ctx.beginPath();ctx.arc(a,b,4,0,7);ctx.fillStyle='#e0e9e2';ctx.fill();}));}}ctx.restore();}
function rover(x,y,angle){ctx.save();ctx.translate(x,y);ctx.rotate(angle);ctx.fillStyle='#254c48';ctx.globalAlpha=.12;ctx.beginPath();ctx.ellipse(0,8,62,11,0,0,7);ctx.fill();ctx.globalAlpha=1;round(-52,-65,104,60,22,'#f6f1d9','#405e58');round(-18,-56,61,32,10,'#234744');line(-5,-39,0,-44,'#8be3d5',3);line(0,-44,5,-39,'#8be3d5',3);line(22,-39,27,-44,'#8be3d5',3);line(27,-44,32,-39,'#8be3d5',3);[-31,33].forEach(a=>{ctx.beginPath();ctx.ellipse(a,0,14,18,0,0,7);ctx.fillStyle='#294c49';ctx.fill();ctx.beginPath();ctx.arc(a,0,6,0,7);ctx.fillStyle='#e29a4b';ctx.fill();});line(-42,-50,-47,-104,'#3d6158',4);poly([[-47,-103],[-77,-98],[-75,-78],[-45,-84]],'#dc773d');ctx.fillStyle='#547167';ctx.font='bold 12px Segoe UI';ctx.textAlign='center';ctx.fillText(state.load,-31,-30);ctx.restore();}
function draw(){ctx.clearRect(0,0,1100,490);const sky=ctx.createLinearGradient(0,0,0,490);sky.addColorStop(0,'#d7e9db');sky.addColorStop(1,'#eff0cf');ctx.fillStyle=sky;ctx.fillRect(0,0,1100,490);ctx.fillStyle='#f6f4d8';ctx.beginPath();ctx.arc(840,85,41,0,7);ctx.fill();poly([[0,210],[140,87],[290,199],[420,118],[600,233],[780,107],[960,213],[1100,120],[1100,490],[0,490]],'#b5cdb3');poly([[0,264],[170,178],[300,262],[450,194],[640,268],[820,178],[1100,263],[1100,490],[0,490]],'#9ebd9e');ctx.fillStyle='#72b5b0';ctx.fillRect(0,340,1100,150);poly([[470,340],[630,340],[840,490],[260,490]],'#94cfcb');for(let i=0;i<19;i++){const x=(i*157)%1100,y=369+(i*23)%115;line(x,y,x+45+(i%3)*18,y,'#b5dfd0',2);}tree(80,211,1.1);tree(1020,217,1.3);tree(180,224,.65);tree(939,241,.7);poly([[0,271],[195,267],[252,296],[215,329],[237,383],[197,414],[220,490],[0,490]],'#8d9983');poly([[0,299],[140,293],[179,328],[145,371],[185,409],[142,490],[0,490]],'#a8af94');poly([[900,267],[1100,277],[1100,490],[878,490],[897,417],[867,376],[894,325],[858,296]],'#889580');poly([[970,293],[1100,294],[1100,490],[949,490],[978,417],[938,368]],'#a7ae93');round(0,265,247,24,7,'#728f62');round(853,265,247,24,7,'#728f62');[0,1,2].forEach(i=>span(250+i*200,state.slots[i],i));round(219,286,28,95,5,'#b1b49a','#808d79');round(853,286,28,95,5,'#b1b49a','#808d79');
let x=145,y=265,angle=0;const t=state.elapsed;if(state.result){if(state.result.passes)x=145+Math.min(1,t/3800)*820;else{ x=145+Math.min(1,t/2200)*400;const f=Math.max(0,Math.min(1,(t-2050)/1300));y+=f*f*230;angle=f*.6;}}rover(x,y,angle);
ctx.textAlign='left';ctx.fillStyle='#e7efdc';ctx.font='bold 10px Segoe UI';ctx.fillText('WEST BANK',28,315);ctx.textAlign='right';ctx.fillText('EAST BANK',1070,315);if(state.mode==='result'&&state.result.passes){ctx.fillStyle='#315c43';ctx.font='bold 22px Segoe UI';ctx.textAlign='center';ctx.fillText('CROSSING COMPLETE ✓',550,155);}if(state.mode==='result'&&!state.result.passes){for(let i=0;i<5;i++){line(540+i*15,457,535+i*20,435-(i%2)*15,'#d8efe0',5);}}
}
window.render_game_to_text=()=>JSON.stringify({coordinates:'Canvas 1100×490; origin top left; x right, y down',...state,totals:simulateBridge(state.slots,state.load)});
window.advanceTime=ms=>{update(ms);draw();};let last=performance.now();function frame(now){update(Math.min(50,now-last));last=now;draw();requestAnimationFrame(frame);}requestAnimationFrame(frame);
function fullscreen(){if(document.fullscreenElement)document.exitFullscreen();else document.documentElement.requestFullscreen?.();}$('fullscreen').addEventListener('click',fullscreen);document.addEventListener('keydown',e=>{if(e.key.toLowerCase()==='f'&&e.target.tagName!=='SELECT')fullscreen();});document.addEventListener('visibilitychange',()=>{if(document.hidden&&state.mode==='testing'){state.paused=true;sync();}});sync();draw();
